const { open, load, log } = require("./lib.cjs");
const fs = require("fs");
(async () => {
  const { browser, page, reqs } = await open();
  await load(page, "chrome-justified-mixed.pdf");
  const short = (from) => reqs.slice(from).filter(r=>r.u).map((r) => r.m + " " + r.u.replace(/^https:\/\/[^/]+/, "").slice(0, 110) + (r.len ? " body=" + r.len : ""));
  const opt = page.getByRole("option", { name: /This agreement is made/ });
  const b = await opt.boundingBox(); log("opt box", JSON.stringify(b));
  log("opt html", (await opt.evaluate((e) => e.outerHTML)).slice(0, 600));
  let mark = reqs.length;
  await page.mouse.click(b.x + 200, b.y + b.height / 2);
  await page.waitForTimeout(1500);
  log("after click reqs", short(mark));
  await page.screenshot({ path: __dirname + "/out/ex2-open.png" });
  const active = await page.evaluate(() => { const a = document.activeElement; return a ? a.outerHTML.slice(0, 1500) : null; });
  log("active", active);
  const sel = await page.evaluate(() => { const s = getSelection(); return { type: s.type, text: s.toString(), off: s.anchorOffset, node: s.anchorNode && s.anchorNode.textContent.slice(0, 60) }; });
  log("selection", JSON.stringify(sel));
  mark = reqs.length;
  await page.keyboard.press("End");
  await page.keyboard.type(" for Dvořák", { delay: 80 });
  await page.waitForTimeout(2500);
  log("after typing reqs", short(mark));
  await page.screenshot({ path: __dirname + "/out/ex2-typed.png" });
  const snap = await page.locator('region[aria-label^="Editing"], [role=region]').first().ariaSnapshot().catch(() => "");
  fs.writeFileSync(__dirname + "/out/ex2-aria.txt", await page.locator("body").ariaSnapshot());
  fs.writeFileSync(__dirname + "/out/ex2-dom.html", await page.content());
  const a2 = await page.evaluate(() => { const a = document.activeElement; let p = a; for (let i = 0; i < 3 && p.parentElement; i++) p = p.parentElement; return p.outerHTML.slice(0, 6000); });
  log("around active", a2);
  log("errors", JSON.stringify(reqs.filter((r) => r.console || r.pageerror)));
  await browser.close();
})().catch((e) => { console.error(String(e).slice(0, 800)); process.exit(1); });
